#define MAX_DOMAIN_LEN 100
char domain[MAX_DOMAIN_LEN];
int status;

// Retrieve the NIS domain name
status = getdomainname(domain, MAX_DOMAIN_LEN);

if (status == 0) {
    // domain is null-terminated.
    // WARNING: glibc truncates if length >= MAX_DOMAIN_LEN.
} else {
    // Handle error
    if (errno == EINVAL) {
        // Buffer too small (MAX_DOMAIN_LEN exceeded)
    }
}
